-- Substitui o catálogo de exames (seed inicial da migração 032, feito
-- a partir de uma lista interna do código que tinha nomes/códigos TUSS
-- incorretos — confirmado comparando com a Tabela 22 oficial da TUSS)
-- pela tabela completa fornecida pelo responsável clínico (arquivo
-- tuss-22_20261014.csv, ANS, 5.969 procedimentos).
--
-- A TUSS não tem no arquivo um campo "tipo" nem "exame vs. não-exame":
-- o que existe são faixas de código (2 primeiros dígitos) que
-- correspondem a capítulos oficiais (10=Consultas, 20=Terapias,
-- 30/31=Cirurgia, 40/41=Diagnóstico — onde exames de laboratório e de
-- imagem ficam —, 50=Atendimento/Internação, 81-87=Odontologia).
-- Dentro de 40/41 a classificação Laboratorial/Imagem é uma estimativa
-- por palavra-chave no nome do procedimento: o que não bateu com
-- nenhuma palavra-chave de laboratório nem de imagem entra como
-- "Diagnóstico" (categoria genérica) em vez de forçar uma classe errada
-- — revise e corrija pela tela de Administração quando notar um item
-- mal classificado.
BEGIN;

ALTER TABLE public.exames DROP CONSTRAINT exames_tipo_check;
ALTER TABLE public.exames ADD CONSTRAINT exames_tipo_check
  CHECK (tipo IN ('Laboratorial','Imagem','Diagnóstico','Consulta','Terapia','Cirurgia','Atendimento','Odontologia'));

DELETE FROM public.exames;

